/** Product account billing. Every provider operation follows a committed, immutable local operation tuple. */
@Service
@ConditionalOnProperty(name="frame.product.enabled",havingValue="true")
public class Memberships {
    public record Plan(UUID channelId,int version,boolean enabled,long amount,String currency,String benefits,long updatedAtMs,boolean paymentsReady){}
    public record Channel(UUID id,String handle,String displayName){}
    public record Subscriber(UUID channelId,String handle,String displayName){}
    public record Member(UUID id,Channel channel,Subscriber subscriber,long amount,String currency,String benefits,int planVersion,String status,int version,long createdAtMs,Long periodStartedAtMs,Long periodEndsAtMs,Long nextChargeAtMs,Long cancelRequestedAtMs,Long endedAtMs,String lastErrorCode,String cardLabel,String billingKeyDeletion,boolean entitled,boolean paymentPending){}
    public record Payment(UUID id,UUID subscriptionId,String orderId,long amount,String currency,String status,long createdAtMs,Long approvedAtMs,String method,String receiptUrl,String errorCode,Long periodStartedAtMs,Long periodEndsAtMs){}
    public record Signup(int status,Map<String,Object> body){}
    private record Row(UUID id,UUID user,UUID channel,UUID request,String customer,int planVersion,long amount,String benefits,String orderName,String status,int version,String authHash,UUID issueKey,String billingKey,String deletion,UUID deleteKey,int deleteAttempts,long created,Long start,Long end,Long nextCharge,Long cancel,Long ended,String error,String card,String handle,String name,UUID subscriberChannel,String subscriberHandle,String subscriberName,boolean paymentPending){@Override public String toString(){return "Membership[id="+id+"]";}}
    private record Authorization(UUID id,String auth){@Override public String toString(){return "Authorization[redacted]";}}
    private record Charge(UUID id,UUID membership,UUID user,String order,long amount,String key,String status,Row member){@Override public String toString(){return "Charge[id="+id+"]";}}
    private static final ZoneId SEOUL=ZoneId.of("Asia/Seoul");
    static final String CONSENT_VERSION="2026-11-17";
    private static final SecureRandom RANDOM=new SecureRandom();
    private static final String BASE="""
            SELECT m.*,c.handle,c.display_name,sc.id AS subscriber_channel,sc.handle AS subscriber_handle,a.display_name AS subscriber_name,
              EXISTS(SELECT 1 FROM product_membership_payments p WHERE p.membership_id=m.id AND p.status IN ('ready','sending','unknown')) AS payment_pending
            FROM product_memberships m JOIN product_channels c ON c.id=m.channel_id JOIN product_channels sc ON sc.owner_id=m.subscriber_id JOIN product_accounts a ON a.id=m.subscriber_id
            """;
    private final JdbcClient sql;private final JsonMapper json;private final MembershipGateway gateway;private final TransactionTemplate tx;
    private final ArrayBlockingQueue<Authorization> authorizations=new ArrayBlockingQueue<>(32);
    private boolean recovered;private Runnable completion;
    public Memberships(JdbcClient sql,JsonMapper json,MembershipGateway gateway,PlatformTransactionManager transactions){this.sql=sql;this.json=json;this.gateway=gateway;this.tx=new TransactionTemplate(transactions);tx.setTimeout(3);}
    private <T>T write(Supplier<T> action){return tx.execute(status->{sql.sql("SET LOCAL statement_timeout='1500ms'").update();sql.sql("SET LOCAL lock_timeout='1000ms'").update();return action.get();});}
    private UUID own(UUID user,boolean lock){return sql.sql("SELECT id FROM product_channels WHERE owner_id=:user"+(lock?" FOR UPDATE":"")).param("user",user).query(UUID.class).optional().orElseThrow(Memberships::unauthenticated);}
    private void account(UUID user){if(sql.sql("SELECT id FROM product_accounts WHERE id=:user FOR NO KEY UPDATE").param("user",user).query(UUID.class).optional().isEmpty())throw unauthenticated();}
    private Plan planForChannel(UUID channel){return sql.sql("SELECT * FROM product_membership_plans WHERE channel_id=:channel").param("channel",channel).query((r,i)->new Plan(channel,r.getInt("version"),r.getBoolean("enabled"),r.getLong("amount"),"KRW",r.getString("benefits"),r.getLong("updated_at_ms"),gateway.configured())).optional().orElseGet(()->new Plan(channel,0,false,4900,"KRW","",0,gateway.configured()));}
    public Map<String,Object> plan(UUID owner){return result(owner,"item",planForChannel(own(owner,false)));}
    public Map<String,Object> updatePlan(UUID owner,JsonNode input){
        exact(input,"version","enabled","amount","benefits","clientRequestId");int version=number(input.path("version"),0);boolean enabled=bool(input.path("enabled"));long amount=amount(input.path("amount"));String benefits=benefits(input.path("benefits"));UUID request=id(input.path("clientRequestId"));String hash=digest(List.of(version,enabled,amount,benefits));
        return write(()->{UUID channel=own(owner,true);Object receipt=receipt(owner,channel,request,"plan",hash);if(receipt!=null)return result(owner,"item",receipt);Plan current=planForChannel(channel);if(current.version()!=version)throw problem(409,"MEMBERSHIP_PLAN_CONFLICT","다른 화면에서 멤버십 설정이 바뀌었어요. 최신 설정을 불러와 주세요.");
            sql.sql("INSERT INTO product_membership_plans(channel_id,enabled,amount,benefits,version,updated_at_ms) VALUES(:channel,:enabled,:amount,:benefits,1,:now) ON CONFLICT(channel_id) DO UPDATE SET enabled=excluded.enabled,amount=excluded.amount,benefits=excluded.benefits,version=product_membership_plans.version+1,updated_at_ms=greatest(excluded.updated_at_ms,product_membership_plans.updated_at_ms)")
                    .param("channel",channel).param("enabled",enabled).param("amount",amount).param("benefits",benefits).param("now",now()).update();
            if(!enabled){for(UUID member:sql.sql("SELECT id FROM product_memberships WHERE channel_id=:channel AND ended_at_ms IS NULL ORDER BY id FOR UPDATE").param("channel",channel).query(UUID.class).list())stop(row(member,true),now());}
            Plan item=planForChannel(channel);saveReceipt(owner,channel,request,"plan",hash,item);return result(owner,"item",item);});
    }
    public Map<String,Object> planReceipt(UUID owner,UUID request){UUID channel=own(owner,false);Object item=receipt(owner,channel,request,null,null);if(item==null)throw missing();return result(owner,"item",item);}
    public Map<String,Object> channel(UUID channel,UUID viewer){
        if(!sql.sql("SELECT EXISTS(SELECT 1 FROM product_channels WHERE id=:channel)").param("channel",channel).query(Boolean.class).single())throw missing();
        var out=result(viewer,"plan",planForChannel(channel));Row member=viewer==null?null:sql.sql(BASE+" WHERE m.subscriber_id=:user AND m.channel_id=:channel ORDER BY (m.ended_at_ms IS NULL) DESC,m.created_at_ms DESC,m.id DESC LIMIT 1").param("user",viewer).param("channel",channel).query(this::row).optional().orElse(null);out.put("membership",member==null?null:view(member));return out;
    }
    public Signup create(UUID user,JsonNode input){
        exact(input,"channelId","planVersion","clientRequestId","consentVersion");if(!input.path("consentVersion").isString()||!CONSENT_VERSION.equals(input.path("consentVersion").asString()))throw problem(400,"MEMBERSHIP_CONSENT_REQUIRED","월 정기결제 안내를 확인하고 동의해 주세요.");UUID channel=id(input.path("channelId")),request=id(input.path("clientRequestId"));int version=number(input.path("planVersion"),1);
        return write(()->{account(user);Row previous=sql.sql(BASE+" WHERE m.subscriber_id=:user AND m.client_request_id=:request").param("user",user).param("request",request).query(this::row).optional().orElse(null);if(previous!=null){if(!previous.channel().equals(channel)||previous.planVersion()!=version)throw requestConflict();return new Signup(200,checkout(user,previous));}
            if(!gateway.configured())throw unavailable();UUID owner=sql.sql("SELECT owner_id FROM product_channels WHERE id=:channel FOR SHARE").param("channel",channel).query(UUID.class).optional().orElseThrow(Memberships::missing);if(owner.equals(user))throw problem(400,"MEMBERSHIP_SELF_JOIN","내 채널의 멤버십에는 가입할 수 없어요.");Plan plan=planForChannel(channel);if(!plan.enabled())throw problem(409,"MEMBERSHIP_PLAN_DISABLED","지금은 이 채널의 멤버십에 가입할 수 없어요.");if(plan.version()!=version)throw problem(409,"MEMBERSHIP_PLAN_CONFLICT","멤버십 가격이나 혜택이 바뀌었어요. 최신 내용을 확인해 주세요.");
            if(sql.sql("SELECT EXISTS(SELECT 1 FROM product_memberships WHERE subscriber_id=:user AND channel_id=:channel AND ended_at_ms IS NULL)").param("user",user).param("channel",channel).query(Boolean.class).single())throw problem(409,"MEMBERSHIP_ALREADY_EXISTS","이미 가입했거나 확인 중인 멤버십이 있어요. 기존 내역을 먼저 확인해 주세요.");
            UUID id=UUID.randomUUID();String name=sql.sql("SELECT display_name FROM product_channels WHERE id=:channel").param("channel",channel).query(String.class).single()+" 멤버십 월 정기결제";
            sql.sql("INSERT INTO product_memberships(id,subscriber_id,channel_id,client_request_id,consent_version,consented_at_ms,customer_key,plan_version,amount,benefits,order_name,status,issue_idempotency_key,delete_idempotency_key,created_at_ms) VALUES(:id,:user,:channel,:request,:consent,:now,:customer,:version,:amount,:benefits,:name,'pending_auth',:issue,:delete,:now)")
                    .param("id",id).param("user",user).param("channel",channel).param("request",request).param("consent",CONSENT_VERSION).param("customer",customer()).param("version",version).param("amount",plan.amount()).param("benefits",plan.benefits()).param("name",name).param("issue",UUID.randomUUID()).param("delete",UUID.randomUUID()).param("now",now()).update();return new Signup(201,checkout(user,row(id,false)));});
    }
    public Map<String,Object> signupReceipt(UUID user,UUID request){Row member=sql.sql(BASE+" WHERE m.subscriber_id=:user AND m.client_request_id=:request").param("user",user).param("request",request).query(this::row).optional().orElseThrow(Memberships::missing);return checkout(user,member);}
    private Map<String,Object> checkout(UUID user,Row member){var out=result(user,"item",view(member));out.put("checkout",member.status().equals("pending_auth")&&member.cancel()==null&&gateway.configured()?Map.of("clientKey",gateway.clientKey(),"customerKey",member.customer(),"subscriptionId",member.id()):null);return out;}
    public Map<String,Object> authorize(UUID user,UUID id,JsonNode input){
        exact(input,"authKey","customerKey","clientRequestId");String auth=opaque(input.path("authKey"),300),customer=opaque(input.path("customerKey"),64);UUID request=id(input.path("clientRequestId"));String hash=DeveloperSettings.hash(auth);recover();
        synchronized(authorizations){
            boolean[] enqueue={false};Map<String,Object> result=write(()->{account(user);Row member=owned(user,id,true);if(!member.request().equals(request)||!member.customer().equals(customer))throw requestConflict();if(member.authHash()!=null){if(!member.authHash().equals(hash))throw requestConflict();return result(user,"item",view(member));}if(!member.status().equals("pending_auth")||member.cancel()!=null)throw conflict();if(!gateway.configured())throw unavailable();if(authorizations.remainingCapacity()==0)throw problem(503,"MEMBERSHIP_BUSY","결제 인증 확인이 많아요. 잠시 후 같은 요청을 다시 확인해 주세요.");
                if(sql.sql("SELECT EXISTS(SELECT 1 FROM product_memberships WHERE auth_hash=:hash AND id<>:id)").param("hash",hash).param("id",id).query(Boolean.class).single())throw requestConflict();
                sql.sql("UPDATE product_memberships SET auth_hash=:hash,status='issuing',version=version+1 WHERE id=:id").param("hash",hash).param("id",id).update();enqueue[0]=true;return result(user,"item",view(row(id,false)));});
            if(enqueue[0])authorizations.add(new Authorization(id,auth));return result;
        }
    }
    public Map<String,Object> detail(UUID user,UUID id){return result(user,"item",view(owned(user,id,false)));}
    public Map<String,Object> cancel(UUID user,UUID id,JsonNode input){exact(input,"version","clientRequestId");int version=number(input.path("version"),1);UUID request=id(input.path("clientRequestId"));String hash=digest(List.of(version));return write(()->{account(user);Object saved=receipt(user,id,request,"cancel",hash);if(saved!=null)return result(user,"item",saved);Row member=owned(user,id,true);if(member.version()!=version)throw conflict();if(member.cancel()==null&&member.ended()==null)stop(member,now());Member item=view(row(id,false));saveReceipt(user,id,request,"cancel",hash,item);return result(user,"item",item);});}
    public Map<String,Object> cancelReceipt(UUID user,UUID id,UUID request){owned(user,id,false);Object saved=receipt(user,id,request,null,null);if(saved==null)throw missing();return result(user,"item",saved);}
    public Map<String,Object> mine(UUID user){own(user,false);var rows=sql.sql(BASE+" WHERE m.subscriber_id=:user ORDER BY (m.ended_at_ms IS NULL) DESC,m.created_at_ms DESC,m.id DESC LIMIT 100").param("user",user).query(this::row).list();var out=result(user,"items",rows.stream().map(this::view).toList());out.put("nextCursor",null);out.put("serverNowMs",now());return out;}
    public Map<String,Object> members(UUID owner,String status,String query,String from,String to,String cursor,int limit){
        UUID channel=own(owner,false);if(!Set.of("all","active","ended").contains(status)||query.codePointCount(0,query.length())>100||query.codePoints().anyMatch(Character::isISOControl)||limit<1||limit>100)throw invalid();
        long[] range=dates(from,to);ProductNotifications.Cursor after;try{after=ProductNotifications.decode(cursor);}catch(ProductProblem error){throw invalid();}
        String statement=BASE+" WHERE m.channel_id=:channel AND position(lower(:q) IN lower(a.display_name))>0 AND m.created_at_ms>=:from AND m.created_at_ms<:to";
        if(status.equals("active"))statement+=" AND m.period_ends_at_ms>:now";if(status.equals("ended"))statement+=" AND (m.ended_at_ms IS NOT NULL OR m.period_ends_at_ms<=:now)";if(after!=null)statement+=" AND (m.created_at_ms,m.id)<(:at,:id)";
        var request=sql.sql(statement+" ORDER BY m.created_at_ms DESC,m.id DESC LIMIT :limit").param("channel",channel).param("q",query.strip()).param("from",range[0]).param("to",range[1]).param("limit",limit+1);if(!status.equals("all"))request.param("now",now());if(after!=null)request.param("at",after.at()).param("id",after.id());
        List<Row> rows=request.query(this::row).list();boolean more=rows.size()>limit;if(more)rows=List.copyOf(rows.subList(0,limit));var out=result(owner,"items",rows.stream().map(this::view).toList());Row last=more?rows.getLast():null;out.put("nextCursor",last==null?null:ProductNotifications.encode(last.created(),last.id()));out.put("serverNowMs",now());return out;
    }
    public Map<String,Object> member(UUID owner,UUID id){UUID channel=own(owner,false);Row member=row(id,false);if(!member.channel().equals(channel))throw missing();return result(owner,"item",view(member));}
    public Map<String,Object> payments(UUID user,UUID id){owned(user,id,false);return result(user,"items",sql.sql("SELECT * FROM product_membership_payments WHERE membership_id=:id AND subscriber_id=:user ORDER BY created_at_ms DESC,id DESC LIMIT 100").param("id",id).param("user",user).query(this::payment).list());}
    /** Reconciliation is a read-only provider action requested on the same single worker; it never repeats a charge. */
    public Map<String,Object> reconcile(UUID user,UUID id,JsonNode input){exact(input);return write(()->{account(user);owned(user,id,true);sql.sql("UPDATE product_membership_payments SET next_lookup_at_ms=:now WHERE membership_id=:id AND status='unknown'").param("now",now()).param("id",id).update();return result(user,"item",view(row(id,false)));});}

    public synchronized void recover(){if(recovered)return;write(()->{
        sql.sql("UPDATE product_memberships SET status=CASE WHEN cancel_requested_at_ms IS NULL THEN 'issue_unknown' ELSE 'ended' END,ended_at_ms=CASE WHEN cancel_requested_at_ms IS NULL THEN NULL ELSE greatest(:now,created_at_ms) END,billing_key_deletion=CASE WHEN cancel_requested_at_ms IS NULL THEN billing_key_deletion ELSE 'unknown' END,last_error_code='MEMBERSHIP_ISSUE_UNCERTAIN',version=version+1 WHERE status='issuing'").param("now",now()).update();
        sql.sql("UPDATE product_membership_payments SET status='unknown',next_lookup_at_ms=:now,error_code='MEMBERSHIP_PAYMENT_UNCERTAIN' WHERE status='sending'").param("now",now()).update();return null;});recovered=true;}
    /** Called only by the one worker. A failed DB completion retains one result and never replays provider mutation. */
    void processOne(){recover();if(completion!=null){completion.run();completion=null;return;}write(()->{expire();return null;});
        Authorization authorization=authorizations.poll();if(authorization!=null){Row member=write(()->{Row row=row(authorization.id(),true);if(row.cancel()!=null){sql.sql("UPDATE product_memberships SET status='ended',ended_at_ms=greatest(:now,created_at_ms),version=version+1 WHERE id=:id").param("now",now()).param("id",row.id()).update();return null;}return row.status().equals("issuing")?row:null;});if(member==null)return;
            try{MembershipGateway.Billing issued=gateway.issue(authorization.auth(),member.customer(),member.issueKey().toString());completion=()->finishIssue(member,issued,null);}catch(MembershipGateway.Failure failure){completion=()->finishIssue(member,null,failure);}catch(RuntimeException failure){completion=()->finishIssue(member,null,new MembershipGateway.Failure("MEMBERSHIP_ISSUE_UNCERTAIN",false));}complete();return;}
        Charge charge=write(this::claimCharge);if(charge!=null){try{MembershipGateway.Payment paid=gateway.charge(charge.member().billingKey(),charge.member().customer(),charge.order(),charge.member().orderName(),charge.amount(),charge.key());completion=()->finishPayment(charge,paid,null,false);}catch(MembershipGateway.Failure failure){completion=()->finishPayment(charge,null,failure,false);}catch(RuntimeException failure){completion=()->finishPayment(charge,null,new MembershipGateway.Failure("MEMBERSHIP_PAYMENT_UNCERTAIN",false),false);}complete();return;}
        Charge unknown=write(this::claimLookup);if(unknown!=null){try{MembershipGateway.Payment found=gateway.lookup(unknown.order());completion=()->finishPayment(unknown,found,null,true);}catch(MembershipGateway.Failure failure){completion=()->finishPayment(unknown,null,failure,true);}catch(RuntimeException failure){completion=()->finishPayment(unknown,null,new MembershipGateway.Failure("MEMBERSHIP_PAYMENT_UNCERTAIN",false),true);}complete();return;}
        Row deletion=write(this::claimDeletion);if(deletion!=null){try{gateway.delete(deletion.billingKey(),deletion.deleteKey().toString());completion=()->finishDeletion(deletion,true,null);}catch(MembershipGateway.Failure failure){completion=()->finishDeletion(deletion,false,failure.code);}catch(RuntimeException failure){completion=()->finishDeletion(deletion,false,"MEMBERSHIP_KEY_DELETE_UNCERTAIN");}complete();}
    }
    private void complete(){completion.run();completion=null;}
    private void finishIssue(Row original,MembershipGateway.Billing billing,MembershipGateway.Failure failure){write(()->{Row current=row(original.id(),true);
        if(billing!=null&&(!current.customer().equals(billing.customerKey())||billing.billingKey()==null||billing.billingKey().isBlank()))failureMarkerIssue(current,new MembershipGateway.Failure("MEMBERSHIP_ISSUE_UNCERTAIN",false));
        else if(billing!=null&&sql.sql("SELECT EXISTS(SELECT 1 FROM product_memberships WHERE billing_key=:key AND id<>:id)").param("key",billing.billingKey()).param("id",current.id()).query(Boolean.class).single())failureMarkerIssue(current,new MembershipGateway.Failure("MEMBERSHIP_BILLING_KEY_REUSED",false));
        else if(billing==null)failureMarkerIssue(current,failure);
        else{sql.sql("UPDATE product_memberships SET billing_key=:key,card_label=:card,status=CASE WHEN cancel_requested_at_ms IS NULL THEN 'pending_charge' ELSE 'ended' END,ended_at_ms=CASE WHEN cancel_requested_at_ms IS NULL THEN NULL ELSE greatest(:now,created_at_ms) END,billing_key_deletion=CASE WHEN cancel_requested_at_ms IS NULL THEN 'none' ELSE 'pending' END,next_delete_at_ms=CASE WHEN cancel_requested_at_ms IS NULL THEN NULL ELSE :now END,last_error_code=NULL,version=version+1 WHERE id=:id")
                .param("key",billing.billingKey()).param("card",billing.cardLabel(),java.sql.Types.VARCHAR).param("now",now()).param("id",current.id()).update();if(current.cancel()==null)newCharge(row(current.id(),false),0);}
        return null;});}
    private void failureMarkerIssue(Row current,MembershipGateway.Failure failure){boolean terminal=failure.definitive||current.cancel()!=null;
        sql.sql("UPDATE product_memberships SET status=:status,ended_at_ms=:ended,billing_key_deletion=:deletion,last_error_code=:error,version=version+1 WHERE id=:id").param("status",terminal?current.cancel()!=null?"ended":"failed":"issue_unknown").param("ended",terminal?Math.max(now(),current.created()):null,java.sql.Types.BIGINT).param("deletion",current.cancel()!=null&&!failure.definitive?"unknown":"none").param("error",failure.code).param("id",current.id()).update();}
    Charge claimCharge(){
        if(!gateway.configured())return null;
        // Generate one next period only after the paid period ended. Downtime never creates catch-up charges.
        UUID due=sql.sql("SELECT m.id FROM product_memberships m JOIN product_membership_plans p ON p.channel_id=m.channel_id WHERE m.next_charge_at_ms<=:now AND m.cancel_requested_at_ms IS NULL AND m.ended_at_ms IS NULL AND p.enabled AND NOT EXISTS(SELECT 1 FROM product_membership_payments x WHERE x.membership_id=m.id AND x.status IN ('ready','sending','unknown')) ORDER BY m.next_charge_at_ms,m.id LIMIT 1 FOR UPDATE OF m").param("now",now()).query(UUID.class).optional().orElse(null);
        if(due!=null){Row member=row(due,false);int cycle=sql.sql("SELECT coalesce(max(cycle),-1)+1 FROM product_membership_payments WHERE membership_id=:id").param("id",due).query(Integer.class).single();newCharge(member,cycle);}
        UUID next=sql.sql("SELECT p.id FROM product_membership_payments p JOIN product_memberships m ON m.id=p.membership_id WHERE p.status='ready' ORDER BY p.created_at_ms,p.id LIMIT 1 FOR UPDATE OF m,p").query(UUID.class).optional().orElse(null);if(next==null)return null;Charge charge=charge(next);Row member=charge.member();
        if(member.cancel()!=null||!planForChannel(member.channel()).enabled()||member.billingKey()==null){sql.sql("UPDATE product_membership_payments SET status='failed',error_code='MEMBERSHIP_CANCELED' WHERE id=:id").param("id",next).update();stop(row(member.id(),false),now());return null;}
        sql.sql("UPDATE product_membership_payments SET status='sending',sent_at_ms=:now,next_lookup_at_ms=:lookup WHERE id=:id AND status='ready'").param("now",now()).param("lookup",now()+30_000).param("id",next).update();return charge;
    }
    private void newCharge(Row member,int cycle){UUID id=UUID.randomUUID();sql.sql("INSERT INTO product_membership_payments(id,membership_id,subscriber_id,cycle,order_id,amount,idempotency_key,status,created_at_ms) VALUES(:id,:member,:user,:cycle,:order,:amount,:key,'ready',:now)").param("id",id).param("member",member.id()).param("user",member.user()).param("cycle",cycle).param("order","frame_mbr_"+id.toString().replace("-","")).param("amount",member.amount()).param("key",UUID.randomUUID()).param("now",now()).update();}
    Charge claimLookup(){if(!gateway.configured())return null;UUID id=sql.sql("SELECT p.id FROM product_membership_payments p JOIN product_memberships m ON m.id=p.membership_id WHERE p.status='unknown' AND (p.next_lookup_at_ms IS NULL OR p.next_lookup_at_ms<=:now) ORDER BY p.next_lookup_at_ms NULLS FIRST,p.id LIMIT 1 FOR UPDATE OF m,p").param("now",now()).query(UUID.class).optional().orElse(null);if(id==null)return null;sql.sql("UPDATE product_membership_payments SET next_lookup_at_ms=:next WHERE id=:id").param("next",now()+30_000).param("id",id).update();return charge(id);}
    private void finishPayment(Charge original,MembershipGateway.Payment paid,MembershipGateway.Failure failure,boolean lookup){write(()->{Row member=row(original.membership(),true);Charge current=charge(original.id());if(Set.of("paid","failed").contains(current.status()))return null;
        if(paid!=null&&(!original.order().equals(paid.orderId())||original.amount()!=paid.amount()||paid.paymentKey()==null||paid.paymentKey().isBlank())){markUnknown(original.id(),"MEMBERSHIP_RESPONSE_INVALID");return null;}
        if(paid!=null&&sql.sql("SELECT EXISTS(SELECT 1 FROM product_membership_payments WHERE payment_key=:key AND id<>:id)").param("key",paid.paymentKey()).param("id",original.id()).query(Boolean.class).single()){markUnknown(original.id(),"MEMBERSHIP_PAYMENT_KEY_REUSED");return null;}
        if(paid!=null&&paid.status().equals("DONE")&&paid.approvedAtMs()>0){long start=Math.max(member.end()==null?0:member.end(),paid.approvedAtMs()),end=monthAfter(start);
            sql.sql("UPDATE product_membership_payments SET status='paid',payment_key=:key,approved_at_ms=:approved,method=:method,receipt_url=:receipt,error_code=NULL,period_started_at_ms=:start,period_ends_at_ms=:end WHERE id=:id")
                    .param("key",paid.paymentKey()).param("approved",paid.approvedAtMs()).param("method",paid.method(),java.sql.Types.VARCHAR).param("receipt",paid.receiptUrl(),java.sql.Types.VARCHAR).param("start",start).param("end",end).param("id",original.id()).update();
            sql.sql("UPDATE product_memberships SET status='active',period_started_at_ms=:start,period_ends_at_ms=:end,next_charge_at_ms=CASE WHEN cancel_requested_at_ms IS NULL THEN :end ELSE NULL END,ended_at_ms=NULL,last_error_code=NULL,version=version+1 WHERE id=:id")
                    .param("start",start).param("end",end).param("id",member.id()).update();return null;}
        boolean terminal=paid!=null&&Set.of("CANCELED","ABORTED","EXPIRED").contains(paid.status())||!lookup&&failure!=null&&failure.definitive;
        if(terminal){String code=failure==null?"MEMBERSHIP_PAYMENT_REJECTED":failure.code;sql.sql("UPDATE product_membership_payments SET status='failed',error_code=:code WHERE id=:id").param("code",code).param("id",original.id()).update();stop(row(member.id(),false),now());sql.sql("UPDATE product_memberships SET last_error_code=:code WHERE id=:id").param("code",code).param("id",member.id()).update();}
        else markUnknown(original.id(),failure==null?"MEMBERSHIP_PAYMENT_UNCERTAIN":failure.code);return null;});}
    private void markUnknown(UUID payment,String code){sql.sql("UPDATE product_membership_payments SET status='unknown',next_lookup_at_ms=:next,error_code=:error WHERE id=:id").param("next",now()+30_000).param("error",code).param("id",payment).update();sql.sql("UPDATE product_memberships SET last_error_code=:error,version=version+1 WHERE id=(SELECT membership_id FROM product_membership_payments WHERE id=:id)").param("error",code).param("id",payment).update();}
    Row claimDeletion(){if(!gateway.configured())return null;UUID id=sql.sql("SELECT m.id FROM product_memberships m WHERE m.billing_key_deletion='pending' AND m.billing_key IS NOT NULL AND m.delete_attempts<5 AND (m.next_delete_at_ms IS NULL OR m.next_delete_at_ms<=:now) AND m.status<>'issuing' AND NOT EXISTS(SELECT 1 FROM product_membership_payments p WHERE p.membership_id=m.id AND p.status IN ('ready','sending','unknown')) ORDER BY m.next_delete_at_ms NULLS FIRST,m.id LIMIT 1 FOR UPDATE").param("now",now()).query(UUID.class).optional().orElse(null);if(id==null)return null;sql.sql("UPDATE product_memberships SET delete_attempts=delete_attempts+1,next_delete_at_ms=:next WHERE id=:id").param("next",now()+30_000).param("id",id).update();return row(id,false);}
    private void finishDeletion(Row member,boolean success,String code){write(()->{row(member.id(),true);sql.sql("UPDATE product_memberships SET billing_key=CASE WHEN :success THEN NULL ELSE billing_key END,billing_key_deletion=:state,next_delete_at_ms=:next,last_error_code=CASE WHEN :success THEN last_error_code ELSE :error END,version=version+1 WHERE id=:id")
            .param("success",success).param("state",success?"done":member.deleteAttempts()>=5?"unknown":"pending").param("next",success?null:now()+Math.min(300_000,5000L*(1L<<member.deleteAttempts())),java.sql.Types.BIGINT).param("error",code,java.sql.Types.VARCHAR).param("id",member.id()).update();return null;});}
    private void stop(Row member,long now){
        sql.sql("UPDATE product_membership_payments SET status='failed',error_code='MEMBERSHIP_CANCELED' WHERE membership_id=:id AND status='ready'").param("id",member.id()).update();
        boolean unresolved=sql.sql("SELECT EXISTS(SELECT 1 FROM product_membership_payments WHERE membership_id=:id AND status IN ('sending','unknown'))").param("id",member.id()).query(Boolean.class).single();boolean end=!unresolved&&!member.status().equals("issuing")&&(member.end()==null||member.end()<=now);
        sql.sql("UPDATE product_memberships SET cancel_requested_at_ms=coalesce(cancel_requested_at_ms,greatest(:now,created_at_ms)),next_charge_at_ms=NULL,status=CASE WHEN :end THEN 'ended' ELSE status END,ended_at_ms=CASE WHEN :end THEN greatest(:now,created_at_ms) ELSE ended_at_ms END,billing_key_deletion=CASE WHEN billing_key IS NOT NULL THEN 'pending' WHEN status='issue_unknown' THEN 'unknown' ELSE billing_key_deletion END,next_delete_at_ms=CASE WHEN billing_key IS NOT NULL THEN :now ELSE next_delete_at_ms END,version=version+1 WHERE id=:id")
                .param("now",now).param("end",end).param("id",member.id()).update();
    }
    private void expire(){for(UUID id:sql.sql("SELECT m.id FROM product_memberships m LEFT JOIN product_membership_plans p ON p.channel_id=m.channel_id WHERE m.ended_at_ms IS NULL AND m.status<>'issuing' AND ((m.cancel_requested_at_ms IS NOT NULL AND (m.period_ends_at_ms IS NULL OR m.period_ends_at_ms<=:now)) OR (m.next_charge_at_ms<=:now AND coalesce(p.enabled,false)=false)) AND NOT EXISTS(SELECT 1 FROM product_membership_payments x WHERE x.membership_id=m.id AND x.status IN ('sending','unknown')) ORDER BY m.id LIMIT 50 FOR UPDATE OF m").param("now",now()).query(UUID.class).list())stop(row(id,false),now());}
    private Row owned(UUID user,UUID id,boolean lock){Row row=row(id,lock);if(!row.user().equals(user))throw missing();return row;}
    private Row row(UUID id,boolean lock){return sql.sql(BASE+" WHERE m.id=:id"+(lock?" FOR UPDATE OF m":"")).param("id",id).query(this::row).optional().orElseThrow(Memberships::missing);}
    private Row row(ResultSet r,int i)throws SQLException{return new Row(r.getObject("id",UUID.class),r.getObject("subscriber_id",UUID.class),r.getObject("channel_id",UUID.class),r.getObject("client_request_id",UUID.class),r.getString("customer_key"),r.getInt("plan_version"),r.getLong("amount"),r.getString("benefits"),r.getString("order_name"),r.getString("status"),r.getInt("version"),r.getString("auth_hash"),r.getObject("issue_idempotency_key",UUID.class),r.getString("billing_key"),r.getString("billing_key_deletion"),r.getObject("delete_idempotency_key",UUID.class),r.getInt("delete_attempts"),r.getLong("created_at_ms"),r.getObject("period_started_at_ms",Long.class),r.getObject("period_ends_at_ms",Long.class),r.getObject("next_charge_at_ms",Long.class),r.getObject("cancel_requested_at_ms",Long.class),r.getObject("ended_at_ms",Long.class),r.getString("last_error_code"),r.getString("card_label"),r.getString("handle"),r.getString("display_name"),r.getObject("subscriber_channel",UUID.class),r.getString("subscriber_handle"),r.getString("subscriber_name"),r.getBoolean("payment_pending"));}
    private Member view(Row row){long now=now();return new Member(row.id(),new Channel(row.channel(),row.handle(),row.name()),new Subscriber(row.subscriberChannel(),row.subscriberHandle(),row.subscriberName()),row.amount(),"KRW",row.benefits(),row.planVersion(),row.status(),row.version(),row.created(),row.start(),row.end(),row.cancel()==null?row.nextCharge():null,row.cancel(),row.ended(),row.error(),row.card(),row.deletion(),row.start()!=null&&row.start()<=now&&row.end()!=null&&row.end()>now,row.paymentPending());}
    private Charge charge(UUID id){return sql.sql("SELECT * FROM product_membership_payments WHERE id=:id").param("id",id).query((r,i)->new Charge(id,r.getObject("membership_id",UUID.class),r.getObject("subscriber_id",UUID.class),r.getString("order_id"),r.getLong("amount"),r.getObject("idempotency_key",UUID.class).toString(),r.getString("status"),row(r.getObject("membership_id",UUID.class),false))).single();}
    private Payment payment(ResultSet r,int i)throws SQLException{return new Payment(r.getObject("id",UUID.class),r.getObject("membership_id",UUID.class),r.getString("order_id"),r.getLong("amount"),"KRW",r.getString("status"),r.getLong("created_at_ms"),r.getObject("approved_at_ms",Long.class),r.getString("method"),r.getString("receipt_url"),r.getString("error_code"),r.getObject("period_started_at_ms",Long.class),r.getObject("period_ends_at_ms",Long.class));}
    private Object receipt(UUID user,UUID resource,UUID request,String operation,String hash){return sql.sql("SELECT * FROM product_membership_requests WHERE user_id=:user AND resource_id=:resource AND request_id=:request").param("user",user).param("resource",resource).param("request",request).query((r,i)->{if(operation!=null&&(!operation.equals(r.getString("operation"))||!hash.equals(r.getString("request_hash"))))throw requestConflict();return json.readTree(r.getString("response"));}).optional().orElse(null);}
    private void saveReceipt(UUID user,UUID resource,UUID request,String operation,String hash,Object value){sql.sql("INSERT INTO product_membership_requests(user_id,resource_id,request_id,operation,request_hash,response) VALUES(:user,:resource,:request,:operation,:hash,CAST(:response AS jsonb))").param("user",user).param("resource",resource).param("request",request).param("operation",operation).param("hash",hash).param("response",json.writeValueAsString(value)).update();}
    private String digest(Object input){return DeveloperSettings.hash(json.writeValueAsString(input));}
    static long monthAfter(long at){return Instant.ofEpochMilli(at).atZone(SEOUL).plusMonths(1).toInstant().toEpochMilli();}
    static long[] dates(String from,String to){try{long start=from.isEmpty()?0:LocalDate.parse(from).atStartOfDay(SEOUL).toInstant().toEpochMilli(),end=to.isEmpty()?Long.MAX_VALUE:LocalDate.parse(to).plusDays(1).atStartOfDay(SEOUL).toInstant().toEpochMilli();if(start>=end)throw invalid();return new long[]{start,end};}catch(java.time.DateTimeException error){throw invalid();}}
    static UUID id(String value){if(value==null||!value.matches("(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"))throw invalid();return UUID.fromString(value);}
    private static UUID id(JsonNode value){if(!value.isString())throw invalid();return id(value.asString());}
    private static int number(JsonNode value,int minimum){if(!value.isIntegralNumber()||!value.canConvertToInt()||value.intValue()<minimum)throw invalid();return value.intValue();}
    private static long amount(JsonNode value){if(!value.isIntegralNumber()||!value.canConvertToLong()||value.longValue()<1000||value.longValue()>1_000_000)throw invalid();return value.longValue();}
    static String benefits(JsonNode input){if(!input.isString())throw invalid();String value=Normalizer.normalize(input.asString(),Normalizer.Form.NFC).replace("\r\n","\n").replace('\r','\n').strip();if(value.codePointCount(0,value.length())>500||value.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\t'||Character.getType(c)==Character.FORMAT||Character.getType(c)==Character.SURROGATE))throw invalid();return value;}
    private static String opaque(JsonNode value,int limit){if(!value.isString()||value.asString().isBlank()||value.asString().length()>limit||value.asString().codePoints().anyMatch(Character::isISOControl))throw invalid();return value.asString();}
    private static boolean bool(JsonNode value){if(!value.isBoolean())throw invalid();return value.booleanValue();}
    private static void exact(JsonNode input,String...fields){if(input.size()!=fields.length)throw invalid();for(String field:fields)if(!input.has(field))throw invalid();}
    private static String customer(){byte[] bytes=new byte[32];RANDOM.nextBytes(bytes);return "mbr_"+Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
    private static long now(){return System.currentTimeMillis();}
    private static Map<String,Object> result(UUID user,String field,Object value){var result=new LinkedHashMap<String,Object>();result.put("userId",user);result.put(field,value);return result;}
    static ProductProblem invalid(){return problem(400,"INVALID_MEMBERSHIP_INPUT","멤버십 입력과 검색 조건을 확인해 주세요.");}
    private static ProductProblem missing(){return problem(404,"MEMBERSHIP_NOT_FOUND","멤버십 내역을 찾을 수 없어요.");}
    private static ProductProblem conflict(){return problem(409,"MEMBERSHIP_CONFLICT","멤버십 상태가 바뀌었어요. 최신 내역을 불러와 주세요.");}
    private static ProductProblem requestConflict(){return problem(409,"MEMBERSHIP_REQUEST_CONFLICT","같은 요청의 정보가 달라요. 기존 내역을 확인해 주세요.");}
    private static ProductProblem unavailable(){return problem(503,"MEMBERSHIP_PAYMENTS_UNAVAILABLE","정기결제 서비스를 연결할 수 없어요. 잠시 후 다시 시도해 주세요.");}
    private static ProductProblem unauthenticated(){return problem(401,"UNAUTHENTICATED","다시 로그인해 주세요.");}
    private static ProductProblem problem(int status,String code,String detail){return new ProductProblem(status,code,detail);}
}
